python3 << 'PY'
import json

agent_def = json.load(open('/tmp/agent_def.json'))['Data']['Node']
end_def = json.load(open('/tmp/end_def.json'))['Data']['Node']
ctx_def = json.load(open('/tmp/context_def.json'))['Data']['Node']

flow = json.load(open('BillingDisputeAnalyst.flow'))

AGENT_PROJECT_ID = "62ee6755-cb8e-43e0-bd67-b715cc047b24"
RES_UUID = "87b4f6cf-fdd7-4ef5-b4cf-81b4f0297692"

start_node = flow['nodes'][0]
assert start_node['id'] == 'start'

agent_node = {
    "id": "billingDisputeAgent",
    "type": "uipath.agent.autonomous",
    "typeVersion": agent_def["version"],
    "display": {"label": "Billing Dispute Analyst Agent"},
    "inputs": {
        "systemPrompt": "You are a Billing Dispute Analyst.",
        "userPrompt": "Analyze the billing dispute and return a determination and rationale.",
        "source": AGENT_PROJECT_ID,
        "agentInputVariables": [
            {
                "id": "start__output__disputeDescription",
                "type": "string",
                "binding": "=$vars.start.output.disputeDescription",
                "description": "Bound from $vars.start.output.disputeDescription"
            },
            {
                "id": "start__output__invoiceNumber",
                "type": "string",
                "binding": "=$vars.start.output.invoiceNumber",
                "description": "Bound from $vars.start.output.invoiceNumber"
            }
        ],
        "agentOutputVariables": [
            {"id": "determination", "type": "string"},
            {"id": "rationale", "type": "string"}
        ]
    },
    "outputs": {
        "error": {
            "type": "object",
            "description": "Error information if the node fails",
            "source": "=Error",
            "var": "error"
        }
    }
}

context_node = {
    "id": "billingDisputeSopContext",
    "type": ctx_def["nodeType"],
    "typeVersion": ctx_def["version"],
    "display": {"label": "Billing Dispute SOP Index"},
    "inputs": {
        "source": RES_UUID
    }
}

end_node = {
    "id": "end",
    "type": "core.control.end",
    "typeVersion": end_def["version"],
    "display": {"label": "End"},
    "inputs": {},
    "outputs": {
        "determination": {"source": "=js:$vars.billingDisputeAgent.output.determination"},
        "rationale": {"source": "=js:$vars.billingDisputeAgent.output.rationale"}
    }
}

flow['nodes'] = [start_node, agent_node, context_node, end_node]

flow['edges'] = [
    {
        "id": "eStartAgent",
        "sourceNodeId": "start",
        "sourcePort": "output",
        "targetNodeId": "billingDisputeAgent",
        "targetPort": "input"
    },
    {
        "id": "eAgentEnd",
        "sourceNodeId": "billingDisputeAgent",
        "sourcePort": "success",
        "targetNodeId": "end",
        "targetPort": "input"
    },
    {
        "id": "eAgentContext",
        "sourceNodeId": "billingDisputeAgent",
        "sourcePort": "context",
        "targetNodeId": "billingDisputeSopContext",
        "targetPort": "input"
    }
]

# definitions: keep existing manual trigger def, add agent/end/context defs
existing_types = {d['nodeType'] for d in flow['definitions']}
for d in (agent_def, end_def, ctx_def):
    if d['nodeType'] not in existing_types:
        flow['definitions'].append(d)

flow['variables'] = {
    "globals": [
        {
            "id": "disputeDescription",
            "direction": "in",
            "type": "string",
            "triggerNodeId": "start",
            "description": "Description of the billing dispute"
        },
        {
            "id": "invoiceNumber",
            "direction": "in",
            "type": "string",
            "triggerNodeId": "start",
            "description": "Invoice number the dispute relates to"
        },
        {
            "id": "determination",
            "direction": "out",
            "type": "string",
            "description": "The agent's determination for the billing dispute"
        },
        {
            "id": "rationale",
            "direction": "out",
            "type": "string",
            "description": "The agent's rationale supporting the determination"
        }
    ],
    "nodes": [
        {
            "id": "billingDisputeAgent.output",
            "type": "object",
            "description": "Agent response",
            "binding": {"nodeId": "billingDisputeAgent", "outputId": "output"}
        },
        {
            "id": "billingDisputeAgent.error",
            "type": "object",
            "description": "Error information if the agent fails",
            "binding": {"nodeId": "billingDisputeAgent", "outputId": "error"}
        }
    ],
    "variableUpdates": {}
}

flow['layout'] = {
    "nodes": {
        "start": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "billingDisputeAgent": {"position": {"x": 0, "y": 0}, "size": {"width": 288, "height": 96}, "collapsed": False},
        "billingDisputeSopContext": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "end": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
    }
}

json.dump(flow, open('BillingDisputeAnalyst.flow', 'w'), indent=2)
print("wrote flow")
